import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
const read=n=>JSON.parse(fs.readFileSync(new URL(n,import.meta.url),'utf8'));
export const ninthProof=read('./transition-proof.json');
export const ninthSha=x=>createHash('sha256').update(x).digest('hex');
const R=ninthProof.records,get=(o,p)=>p.reduce((x,k)=>x?.[k],o),set=(o,p,v)=>p.slice(0,-1).reduce((x,k)=>x[k],o)[p.at(-1)]=v;
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b),record=(id,p)=>R.find(r=>r.entryId===id&&same(r.path,p));
for(const r of R){assert.equal(ninthSha(r.before),r.beforeSha256);assert.equal(ninthSha(r.after),r.afterSha256);assert.equal(get(ninthProof.originalEntries[r.entryId],r.path),r.before);assert.equal(get(ninthProof.finalEntries[r.entryId],r.path),r.after);}
export function ninthLeaf(id,p,old){const r=record(id,p);return r&&old===r.before?r.after:old;}
export function ninthHash(id,p,old){const r=record(id,p);return r&&old===r.beforeSha256?r.afterSha256:old;}
export function ninthEntry(old){const next=structuredClone(old);for(const r of R.filter(r=>r.entryId===old.id))if(get(next,r.path)===r.before)set(next,r.path,r.after);return next;}
export function ninthQuestion(id,index,old){assert.ok(Number.isInteger(index)&&index>=0,'ninth question index must be an integer');const next=structuredClone(old);for(const r of R.filter(r=>r.entryId===id&&r.path[0]==='items'&&r.path[1]===index)){const p=r.path.slice(2);if(get(next,p)===r.before)set(next,p,r.after);}return next;}
export function ninthReferenceQuestion(id,index,current){assert.ok(Number.isInteger(index)&&index>=0,'ninth reference index must be an integer');const rs=R.filter(r=>r.entryId===id&&r.path[0]==='items'&&r.path[1]===index);if(!rs.length)return current;assert.deepEqual(current,ninthProof.finalEntries[id].items[index],'exact current full question before ninth historical reference');const old=structuredClone(current);for(const r of rs)set(old,r.path.slice(2),r.before);assert.deepEqual(old,ninthProof.originalEntries[id].items[index]);return old;}
export function ninthReferenceEntry(current){if(!ninthProof.finalEntries[current.id])return current;assert.deepEqual(current,ninthProof.finalEntries[current.id],'exact current full entry before ninth historical reference');const old=structuredClone(current);for(const r of R.filter(r=>r.entryId===current.id))set(old,r.path,r.before);assert.deepEqual(old,ninthProof.originalEntries[current.id]);return old;}
export function assertNinthEntries(E){for(const[id,e]of Object.entries(ninthProof.finalEntries))assert.deepEqual(E.get(id),e,'exact current ninth full entry '+id);return {leaves:31,entries:21};}
export function ninthEntryHash(id,old){const e=ninthProof.originalEntries[id];if(!e)return old;const canon=v=>JSON.stringify((function sort(x){if(Array.isArray(x))return x.map(sort);if(x&&typeof x==='object')return Object.fromEntries(Object.keys(x).sort().map(k=>[k,sort(x[k])]));return x;})(v));return old===ninthSha(canon(e))?ninthSha(canon(ninthProof.finalEntries[id])):old;}
export function ninthFragment(id,p,old){const r=record(id,p);if(!r||!r.segments||!r.before.includes(old)||r.after.includes(old))return old;let out=old;for(const s of r.segments)if(out.includes(s.before)){assert.equal(out.split(s.before).length,2);out=out.replace(s.before,s.after);}if(out!==old)assert.ok(r.after.includes(out),'entire exact migrated fragment');return out;}
export function ninthIncludes(id,p,actual,old){const r=record(id,p);if(!r)return actual.includes(old);assert.equal(actual,r.after,'complete actual ninth leaf required before reference inclusion');if(actual.includes(old))return true;const expected=ninthFragment(id,p,old);return expected!==old&&actual.includes(expected);}
let sourceProof;const sources=()=>sourceProof??=read('./source-transitions.json');
export function ninthSourceText(path,old){const r=sources().replacements.find(r=>r.target===path&&r.before===old);return r?r.after:old;}
export function ninthSourceHash(path,old){const r=sources().replacements.find(r=>r.target===path&&r.beforeSha256===old);return r?r.afterSha256:old;}
export function ninthRegistryBefore(current){const original=read('./original500-registry.json'),expected=structuredClone(original),by=new Map(expected.records.map(r=>[JSON.stringify([r.entryId,r.path]),r]));for(const r of R){const k=JSON.stringify([r.entryId,r.path]),prev=by.get(k);if(prev){assert.equal(prev.after,r.before);prev.after=r.after;prev.afterSha256=r.afterSha256;}else{const n=Object.fromEntries(['entryId','path','before','after','beforeSha256','afterSha256','reason'].map(k=>[k,r[k]]));expected.records.push(n);by.set(k,n);}}assert.deepEqual(current,expected,'entire527 current registry required before exact500 reference');return original;}
export function ninthKeyInfo(E,key){const at=key.lastIndexOf('#');if(at<0)return {id:key,path:['html'],actual:E.get(key)?.html};const id=key.slice(0,at),q=key.slice(at+1),e=E.get(id);assert.ok(e);const matches=/^(0|[1-9]\d*)$/.test(q)?[Number(q)]:e.items.flatMap((it,i)=>it.id!==undefined&&it.id!==null&&String(it.id)===q?[i]:[]);assert.equal(matches.length,1,'ninth key resolves uniquely '+key);const i=matches[0];assert.ok(i>=0&&i<e.items.length,'ninth key index resolves '+key);return {id,path:['items',i,'a'],actual:e.items[i].a};}
export function ninthKeyIncludes(E,key,old){const {id,path,actual}=ninthKeyInfo(E,key);return ninthIncludes(id,path,actual,old);}
export function ninthKeyHash(E,key,old){const {id,path}=ninthKeyInfo(E,key);return ninthHash(id,path,old);}
export function ninthKeyFragment(E,key,old){const {id,path}=ninthKeyInfo(E,key);return ninthFragment(id,path,old);}
export function ninthSubstantiveIncludes(id,p,actual,old){const r=record(id,p);if(r)assert.equal(actual,r.after);const body=actual.replace(/<details\b[^>]*class="qa-(?:variants|related)"[^>]*>[\s\S]*?<\/details>/g,'');return body.includes(ninthFragment(id,p,old));}
const siteRoot=new URL('../../../',import.meta.url);
export function ninthExecutablePath(original){const relative=typeof original==='string'&&original.startsWith('/')?original.slice(new URL(siteRoot).pathname.length):original;const r=sources().clones.find(r=>r.originalTarget===relative);if(!r)return original;assert.equal(ninthSha(fs.readFileSync(new URL(relative,siteRoot))),r.beforeSha256,'original executable remains immutable '+relative);assert.equal(ninthSha(fs.readFileSync(new URL(r.target,siteRoot))),r.afterSha256,'reviewed bridge executable '+r.target);return new URL(r.target,siteRoot).pathname;}
export function ninthExecutionHash(relative,old){const r=sources().clones.find(r=>r.originalTarget===relative&&r.beforeSha256===old);if(!r)return ninthSourceHash(relative,old);ninthExecutablePath(relative);return r.afterSha256;}

export function ninthPlainIncludes(id,p,actual,old,plain){const r=record(id,p);if(r)assert.equal(actual,r.after,'exact current whole leaf before plain historical witness');if(plain(actual).includes(plain(old)))return true;if(!r)return false;const rows=(r.segments??[]).filter(s=>plain(s.before)===plain(old));if(rows.length!==1)return false;assert.ok(r.before.includes(rows[0].before));return actual.includes(rows[0].after);}

export function ninthKeyQuestion(key,old){const at=key.lastIndexOf('#'),id=key.slice(0,at),q=key.slice(at+1),entry=ninthProof.originalEntries[id];if(!entry)return structuredClone(old);if(/^(0|[1-9]\d*)$/.test(q))return ninthQuestion(id,Number(q),old);const indices=entry.items.flatMap((it,i)=>it.id!==undefined&&it.id!==null&&String(it.id)===q?[i]:[]);assert.equal(indices.length,1,'expected-side ninth question key resolves uniquely '+key);return ninthQuestion(id,indices[0],old);}
